/**
 * Firebase Functions entry point for TanStack Start (Nitro SSR).
 * Serves the Nitro SSR handler so all routes (including /admin) work on Firebase.
 */

const { onRequest } = require("firebase-functions/v2/https");

// Lazy-load the Nitro server handler (built by `npm run build`)
let nitroHandler = null;

async function getNitroHandler() {
  if (!nitroHandler) {
    // The .output/server directory is generated by `npm run build`
    // with the Nitro node-server preset for Firebase compatibility
    const nitroModule = await import("../../.output/server/index.mjs");
    nitroHandler = nitroModule.default || nitroModule;
  }
  return nitroHandler;
}

const api = onRequest(
  {
    region: "me-central1",
    timeoutSeconds: 60,
    memory: "256MiB",
  },
  async (req, res) => {
    try {
      const handler = await getNitroHandler();

      const url = new URL(
        `${req.protocol}://${req.host}${req.originalUrl}`
      );

      const headers = {};
      for (const [key, value] of Object.entries(req.headers)) {
        headers[key] = value;
      }

      const fetchRequest = new Request(url.toString(), {
        method: req.method,
        headers,
        body:
          req.method === "GET" || req.method === "HEAD"
            ? null
            : req.rawBody
            ? Buffer.from(req.rawBody)
            : null,
      });

      const nitroResponse = await handler.fetch(fetchRequest);

      res.status(nitroResponse.status);

      for (const [key, value] of nitroResponse.headers.entries()) {
        res.set(key, value);
      }

      const body = await nitroResponse.text();
      res.send(body);
    } catch (err) {
      console.error("Firebase Function error:", err);
      res.status(500).send("Internal Server Error");
    }
  }
);

module.exports = { api };